import{_ as e,o as r,c as o,a6 as a}from"./chunks/framework.B_q3ZJNF.js";const m=JSON.parse('{"title":"关于本课程","description":"","frontmatter":{},"headers":[],"relativePath":"x-video-downloader-course/about.md","filePath":"x-video-downloader-course/docs/about.md"}'),d={name:"x-video-downloader-course/about.md"};function n(i,t,s,l,c,h){return r(),o("div",null,[...t[0]||(t[0]=[a('<h1 id="关于本课程" tabindex="-1">关于本课程 <a class="header-anchor" href="#关于本课程" aria-label="Permalink to &quot;关于本课程&quot;">​</a></h1><blockquote><p><strong>X 的视频，页面上是一串打不开的假地址、网络里是一把几秒的小分片——一个插件怎么把它变回你硬盘上的一个文件？</strong></p></blockquote><p>全书 7 章就是这句话的答案。课程从零写一个真能用的浏览器插件：companion 目录本身就是可直接装载进 Chrome 的 MV3 扩展，零构建、零运行时依赖，随章节逐章长大——第 1 章一个最小骨架（约 80 行），读完时 929 行，76 个测试全绿。</p><ul><li><strong>输入主题</strong>：怎么写一个浏览器插件，下载 X(Twitter) 视频</li><li><strong>读者画像</strong>：会写现代 JS（async/await、fetch、DOM、ESM）、装过插件但没写过的开发者</li><li><strong>终点</strong>：一个装进 Chrome 就能用的 X 视频下载插件——点推文上的下载按钮，磁盘出现可播放文件</li></ul><h2 id="边界声明" tabindex="-1">边界声明 <a class="header-anchor" href="#边界声明" aria-label="Permalink to &quot;边界声明&quot;">​</a></h2><p>本课程仅用于学习浏览器扩展开发：请只下载你拥有版权或已获明确授权的内容，遵守 X 服务条款与当地著作权法。</p><h2 id="内容时效" tabindex="-1">内容时效 <a class="header-anchor" href="#内容时效" aria-label="Permalink to &quot;内容时效&quot;">​</a></h2><p>X 的前端 DOM、内部接口与视频投递方式随版本变化（本课程内容截至 2026-08）。课程教的是标准协议（HLS/RFC 8216）与可迁移的插件开发方法；易变细节（选择器、URL 形态）正文随讲给出现场核对步骤，不为任何快照背书。浏览器 API 行为以 <a href="https://developer.chrome.com/docs/extensions" target="_blank" rel="noreferrer">developer.chrome.com</a> 为准。</p><h2 id="能力阶梯" tabindex="-1">能力阶梯 <a class="header-anchor" href="#能力阶梯" aria-label="Permalink to &quot;能力阶梯&quot;">​</a></h2><p>学完各章，你能：</p><table tabindex="0"><thead><tr><th>章</th><th>你能做什么</th></tr></thead><tbody><tr><td>1. MV3 插件的最小骨架</td><td>装载未打包扩展，分清 content script 与 service worker 两个世界各自能做什么</td></tr><tr><td>2. 让视频现形</td><td>在 DevTools 里同时看到假地址与真请求，让插件后台实时滚出 video.twimg.com 的播放列表地址</td></tr><tr><td>3. 拆开播放列表</td><td>逐行念出 m3u8 两级清单，写出按带宽选最高画质的解析器（测试全绿）</td></tr><tr><td>4. 分片下载管线</td><td>mp4 直链一行落盘；HLS 分片并发抓取、字节拼接，跨环境协作存出可播放的文件</td></tr><tr><td>5. 按钮上推文</td><td>滚动与路由后按钮自动出现，状态机走完全程，正式消息协议接通两个世界</td></tr><tr><td>6. 权限与发布</td><td>给 manifest 每项权限报出凭什么，跑通核对脚本并打出可上架的 zip</td></tr><tr><td>7. 全链路对账</td><td>从点击到落盘每一跳报出环境、API 与凭什么非它不可</td></tr></tbody></table>',11)])])}const u=e(d,[["render",n]]);export{m as __pageData,u as default};
